#!/usr/bin/env python3
"""Build the marketing-only v146 repair from a verified v145 staging tree.

Usage: python3 website_v146_patch.py --source BASELINE --output STAGING
The source is never modified. The output must not already exist.
"""

import argparse
import base64
import gzip
import hashlib
import json
from pathlib import Path
import shutil
import struct
import sys

BASELINE_TEXT_SHA256 = {'index.html': '6ea4de432e42b6ad772ce688a726b439a0ef809f8beb56f081c46b805ccc5b54', 'home-video-preview.html': '3edde4bde02d92a98d7e1755e8550a8e00f6b3f0d615557e5325a96e0bae90fb', 'video-preview/home-video-preview.css': 'c242279212beaa4591b2d6a0d9a04e4247a521540cd9832c7ff9f3952680a0c6', 'video-preview/home-video-playback.js': None}
OUTPUT_TEXT_SHA256 = {'index.html': '46df91a09750dbaf7fe5efb6b7bf5425cb852623e00caa0c8f59def7b3ddf9cc', 'home-video-preview.html': '670c7ad1b578903f22600ecfad2101a77f2adc70ed2d639c062235c1c6e8b589', 'video-preview/home-video-preview.css': 'f8b157cfda5a59d074a9a6de292043afda9232b80f298350ea4a1f7358976a61', 'video-preview/home-video-playback.js': '2e0bc8c924117de976306c50d93404148f2399fd6d2b53b4cbda5129e5ed38b7'}
TEXT_PAYLOAD_GZIP_BASE64 = ''
VIDEO_PREFIX_BASE64 = ''


VIDEO_PATH = 'video-preview/driveforma-owner-film-loop.mp4'
INPUT_VIDEO_SHA256 = 'a608eb378c40113ad8f53788242ad17afa5abea7e7ff0aed4b22b12ce4d98d2d'
OUTPUT_VIDEO_SHA256 = '6392202364f92fd0a64b276ac358573628aa03e866a3407fc7242cb7b608f2dd'
MDAT_PAYLOAD_SHA256 = '52fd84bc57233e9aa2bf7f0aca76275b81fa6bdeecedee48e51607f19e0fd8e8'
INPUT_MDAT_OFFSET = 11589
OUTPUT_MDAT_OFFSET = 9924
MDAT_BYTES = 4750190
OUTPUT_VIDEO_BYTES = 4760114
BASELINE_FILE_COUNT = 270


def digest(data):
    return hashlib.sha256(data).hexdigest()


def require(condition, message):
    if not condition:
        raise ValueError(message)


def tree_manifest(directory):
    result = {}
    for item in directory.rglob('*'):
        require(not item.is_symlink(), f'Symlinks are not allowed: {item.name}')
        if item.is_file():
            result[item.relative_to(directory).as_posix()] = digest(item.read_bytes())
    return result


def build_patch(source, output):
    source = source.resolve()
    output = output.resolve()
    require(source.is_dir(), 'The v145 staging source directory does not exist.')
    require(not output.exists(), 'The output must be a new staging directory.')
    require(source != output, 'The source and output must differ.')
    require(source not in output.parents, 'The output cannot be inside the source.')
    require(output not in source.parents, 'The source cannot be inside the output.')

    baseline = tree_manifest(source)
    require(len(baseline) == BASELINE_FILE_COUNT, 'The baseline file count is not v145.')
    for path, expected in BASELINE_TEXT_SHA256.items():
        require(baseline.get(path) == expected, f'Baseline text mismatch: {path}')

    texts = json.loads(gzip.decompress(base64.b64decode(TEXT_PAYLOAD_GZIP_BASE64, validate=True)))
    require(set(texts) == set(OUTPUT_TEXT_SHA256), 'Unexpected text payload paths.')
    encoded_texts = {}
    for path, content in texts.items():
        relative = Path(path)
        require(not relative.is_absolute() and '..' not in relative.parts, 'Invalid payload path.')
        data = content.encode('utf-8')
        require(digest(data) == OUTPUT_TEXT_SHA256[path], f'Text payload mismatch: {path}')
        encoded_texts[path] = data

    old_video = (source / VIDEO_PATH).read_bytes()
    require(digest(old_video) == INPUT_VIDEO_SHA256, 'The baseline video is not the verified v145 edit.')
    mdat = old_video[INPUT_MDAT_OFFSET:]
    require(len(mdat) == MDAT_BYTES, 'Unexpected media payload length.')
    require(struct.unpack('>I4s', mdat[:8]) == (MDAT_BYTES, b'mdat'), 'Unexpected MP4 media box.')
    require(digest(mdat[8:]) == MDAT_PAYLOAD_SHA256, 'The encoded video frames differ from v145.')
    prefix = base64.b64decode(VIDEO_PREFIX_BASE64, validate=True)
    require(len(prefix) == OUTPUT_MDAT_OFFSET, 'Unexpected corrected MP4 prefix length.')
    new_video = prefix + mdat
    require(len(new_video) == OUTPUT_VIDEO_BYTES, 'Unexpected corrected video length.')
    require(digest(new_video) == OUTPUT_VIDEO_SHA256, 'The corrected video checksum does not match.')

    expected_changed = set(OUTPUT_TEXT_SHA256) | {VIDEO_PATH}
    expected_added = {path for path, value in BASELINE_TEXT_SHA256.items() if value is None}
    created = False
    try:
        shutil.copytree(source, output)
        created = True
        for path, data in encoded_texts.items():
            (output / path).write_bytes(data)
        (output / VIDEO_PATH).write_bytes(new_video)
        actual = tree_manifest(output)
        require(set(actual) == set(baseline) | expected_added, 'The output file set changed unexpectedly.')
        for path, expected in OUTPUT_TEXT_SHA256.items():
            require(actual[path] == expected, f'Output text mismatch: {path}')
        require(actual[VIDEO_PATH] == OUTPUT_VIDEO_SHA256, 'Output video mismatch.')
        for path, expected in baseline.items():
            if path not in expected_changed:
                require(actual[path] == expected, f'Unchanged source was altered: {path}')
    except Exception:
        if created:
            shutil.rmtree(output)
        raise

    return {
        'release': 'v146',
        'result': 'PASS',
        'files': len(actual),
        'changed': sorted(expected_changed),
        'preservedExistingFiles': len(baseline) - len(expected_changed - expected_added),
        'videoSha256': OUTPUT_VIDEO_SHA256,
        'sourceModified': False,
        'encodedVideoFramesPreserved': True,
        'publication': 'Staging only. The caller must publish after this command succeeds.',
    }


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--source', type=Path, required=True)
    parser.add_argument('--output', type=Path, required=True)
    args = parser.parse_args()
    try:
        result = build_patch(args.source, args.output)
    except Exception as error:
        print(f'Website staging patch failed: {error}', file=sys.stderr)
        return 1
    print(json.dumps(result, sort_keys=True))
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
